using System.Collections.Generic;
using Politicmon.Core;
using UnityEngine;

namespace Politicmon.Audio
{
    /// <summary>
    /// Music (looping) and sound effects loaded from Resources/Audio/Music and Resources/Audio/Sfx.
    /// All clips are chiptune WAVs generated by tools/gen_audio.py.
    /// </summary>
    public class AudioManager : MonoBehaviour
    {
        public static AudioManager Instance { get; private set; }

        AudioSource music;
        readonly List<AudioSource> sfxSources = new();
        readonly Dictionary<string, AudioClip> cache = new();

        public string CurrentMusic { get; private set; } = "";
        public bool Muted { get; private set; }

        void Awake()
        {
            Instance = this;
            music = gameObject.AddComponent<AudioSource>();
            music.loop = true;
            music.volume = 0.5f;
            for (int i = 0; i < 4; i++)
            {
                var s = gameObject.AddComponent<AudioSource>();
                s.volume = 0.6f;
                sfxSources.Add(s);
            }
        }

        AudioClip Load(string path)
        {
            if (!cache.TryGetValue(path, out var clip))
                cache[path] = clip = Resources.Load<AudioClip>(path);
            return clip;
        }

        public static void PlayMusic(string name)
        {
            var self = Instance;
            if (self == null || (name == self.CurrentMusic && self.music.isPlaying))
                return;
            self.CurrentMusic = name;
            self.music.Stop();
            var clip = self.Load("Audio/Music/" + name);
            if (clip == null || self.Muted)
                return;
            self.music.clip = clip;
            self.music.Play();
        }

        public static void StopMusic()
        {
            if (Instance == null)
                return;
            Instance.CurrentMusic = "";
            Instance.music.Stop();
        }

        public static void Sfx(string name)
        {
            var self = Instance;
            if (self == null || self.Muted)
                return;
            var clip = self.Load("Audio/Sfx/" + name);
            if (clip == null)
                return;
            var source = self.sfxSources.Find(s => !s.isPlaying) ?? self.sfxSources[0];
            source.clip = clip;
            source.Play();
        }

        /// <summary>Plays a jingle and waits until it ends (capture, level up...).</summary>
        public static async Awaitable SfxAndWait(string name)
        {
            var clip = Instance?.Load("Audio/Sfx/" + name);
            if (clip == null || Instance.Muted)
                return;
            Sfx(name);
            await Async.Seconds(clip.length);
        }

        public static void SetMuted(bool muted)
        {
            var self = Instance;
            if (self == null)
                return;
            self.Muted = muted;
            if (muted)
            {
                self.music.Stop();
            }
            else if (self.CurrentMusic != "")
            {
                string current = self.CurrentMusic;
                self.CurrentMusic = "";
                PlayMusic(current);
            }
        }
    }
}
